            letter-spacing: 0.3px;
        }

        .input-section button:hover {
            background: #2563eb;
            transform: scale(1.02);
        }

        .input-section button:active {
            background: #1d4ed8;
            transform: scale(0.98);
        }

        /* 任务列表 */
        .task-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 0.7rem;
            margin-bottom: 0.5rem;
        }

        .task-item {
            display: flex;
            align-items: center;
            gap: 0.8rem;
            background: #ffffff;
