            transition: all 0.15s;
            box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
        }

        .task-item:hover {
            border-color: #cbd5e1;
            background: #fafcff;
        }

        /* 复选框自定义 */
        .task-checkbox {
            appearance: none;
            -webkit-appearance: none;
            width: 1.5rem;
            height: 1.5rem;
            border: 2px solid #cbd5e1;
            border-radius: 50%;
            background: #ffffff;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: 0.15s;
            flex-shrink: 0;
            position: relative;
        }

        .task-checkbox:checked {
            background: #3b82f6;
            border-color: #3b82f6;
        }

        .task-checkbox:checked::after {
            content: "✓";
            color: white;
            font-size: 1rem;
            font-weight: 600;
            line-height: 1;
            display: block;
            transform: translateY(-1px);
