        }

        .task-item.completed {
            background: #f8fafc;
            border-color: #e2e8f0;
            opacity: 0.85;
        }

        /* 删除按钮 */
        .delete-btn {
            background: transparent;
            border: none;
            width: 2.2rem;
            height: 2.2rem;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.3rem;
            color: #94a3b8;
            cursor: pointer;
            transition: 0.15s;
            flex-shrink: 0;
            line-height: 1;
            font-weight: 400;
            padding: 0;
        }

        .delete-btn:hover {
            background: #fee2e2;
            color: #dc2626;
            transform: scale(1.05);
        }

        .delete-btn:active {
            background: #fecaca;
            transform: scale(0.95);
        }

        /* 空状态提示 */
        .empty-message {
            text-align: center;
            color: #94a3b8;
            padding: 2.5rem 1rem;
            font-size: 1rem;
            border: 2px dashed #e2e8f0;
            border-radius: 60px;
            background: #fafcff;
            margin-top: 0.5rem;
        }

        /* 底部统计 */
        .stats {
            margin-top: 1.5rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 0.9rem;
            color: #64748b;
            padding: 0 0.5rem;
        }

        .stats span {
            background: #f1f5f9;
            padding: 0.3rem 1rem;
            border-radius: 40px;
            font-weight: 500;
        }

        /* 小屏适配 */
        @media (max-width: 480px) {
            .app-container {
                padding: 1.5rem 1.2rem;
            }

            h1 {
                font-size: 1.7rem;
            }

            .input-section button {
                padding: 0.9rem 1.4rem;
            }

            .task-item {
                padding-left: 1rem;
            }
        }
    </style>
</head>
<body>
    <div class="app-container">
        <h1>待办清单</h1>

        <!-- 输入区域：输入框 + 按钮，支持回车提交 -->
        <div class="input-section">
            <input type="text" id="taskInput" placeholder="写一个任务..." autocomplete="off" aria-label="新任务内容">
            <button id="addBtn" type="button">添加</button>
        </div>

        <!-- 任务列表容器 -->
        <ul class="task-list" id="taskList">
            <!-- 动态渲染任务 -->
        </ul>

        <!-- 空状态提示（由JS控制显示/隐藏） -->
        <div id="emptyMessage" class="empty-message" style="display: none;">
            ✨ 还没有任务，添加一条吧
        </div>

        <!-- 底部统计 -->
        <div class="stats">
            <span id="taskCounter">0 项任务</span>
            <span id="completedCounter">0 已完成</span>
        </div>
    </div>

    <script>
        (function() {
            // ---------- 数据层 ----------
            const STORAGE_KEY = 'todo_list_data';

            // 任务数据结构: { id: string, text: string, completed: boolean }
            let tasks = [];

            // 获取 DOM 元素
            const taskInput = document.getElementById('taskInput');
            const addBtn = document.getElementById('addBtn');
            const taskList = document.getElementById('taskList');
            const emptyMessage = document.getElementById('emptyMessage');
            const taskCounter = document.getElementById('taskCounter');
            const completedCounter = document.getElementById('completedCounter');

            // ---------- 工具函数 ----------
            // 生成唯一ID (简单可靠)
            function generateId() {
                return Date.now() + '-' + Math.random().toString(36).substring(2, 10);
            }

            // 从 localStorage 加载数据
            function loadTasks() {
                try {
                    const stored = localStorage.getItem(STORAGE_KEY);
                    if (stored) {
                        const parsed = JSON.parse(stored);
                        // 确保是数组，且每个任务有基本结构
                        if (Array.isArray(parsed)) {
                            tasks = parsed.filter(task => 
                                task && typeof task === 'object' && 
                                typeof task.id === 'string' && 
                                typeof task.text === 'string' && 
                                typeof task.completed === 'boolean'
                            );
                        } else {
                            tasks = [];
                        }
                    } else {
                        tasks = [];
                    }
                } catch (e) {
                    console.warn('读取本地存储失败，使用空列表', e);
                    tasks = [];
                }
            }

            // 保存任务到 localStorage
            function saveTasks() {
                try {
                    localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
                } catch (e) {
                    console.warn('保存到本地存储失败', e);
                }
            }

            // ---------- 渲染视图 ----------
            function render() {
                // 清空列表
                taskList.innerHTML = '';

                // 根据任务数组渲染每一项
                if (tasks.length === 0) {
                    emptyMessage.style.display = 'block';
                } else {
                    emptyMessage.style.display = 'none';
                }

                tasks.forEach(task => {
                    const li = document.createElement('li');
                    li.className = 'task-item' + (task.completed ? ' completed' : '');
                    li.dataset.id = task.id;

                    // 复选框
                    const checkbox = document.createElement('input');
                    checkbox.type = 'checkbox';
                    checkbox.className = 'task-checkbox';
                    checkbox.checked = task.completed;
                    checkbox.setAttribute('aria-label', `标记任务"${task.text}"为${task.completed ? '未完成' : '已完成'}`);
                    // 切换完成状态
                    checkbox.addEventListener('change', (e) => {
                        e.stopPropagation();
                        toggleTaskCompletion(task.id);
                    });

                    // 任务文本
                    const span = document.createElement('span');
                    span.className = 'task-text';
                    span.textContent = task.text;

                    // 删除按钮
                    const delBtn = document.createElement('button');
                    delBtn.className = 'delete-btn';
                    delBtn.innerHTML = '✕'; // 乘号表示删除
                    delBtn.setAttribute('aria-label', `删除任务"${task.text}"`);
                    delBtn.addEventListener('click', (e) => {
                        e.stopPropagation();
                        deleteTask(task.id);
                    });

                    li.appendChild(checkbox);
                    li.appendChild(span);
                    li.appendChild(delBtn);
                    taskList.appendChild(li);
                });

                // 更新统计
                updateStats();
            }

            // 更新底部统计信息
            function updateStats() {
                const total = tasks.length;
                const completed = tasks.filter(t => t.completed).length;
                taskCounter.textContent = `${total} 项任务`;
                completedCounter.textContent = `${completed} 已完成`;
            }

            // ---------- 业务操作 ----------
            // 添加新任务
            function addTask() {
                const text = taskInput.value.trim();
                if (text === '') {
                    // 空内容不添加，可以轻微提示（输入框抖动或聚焦）
                    taskInput.focus();
                    return;
                }

                const newTask = {
                    id: generateId(),
                    text: text,
                    completed: false
                };

                tasks.push(newTask);
                saveTasks();
                render();

                // 清空输入框并保持焦点
                taskInput.value = '';
                taskInput.focus();
            }

            // 切换任务完成状态
            function toggleTaskCompletion(taskId) {
                const task = tasks.find(t => t.id === taskId);
                if (task) {
                    task.completed = !task.completed;
                    saveTasks();
                    render(); // 重新渲染以更新样式和统计
                }
            }

            // 删除任务
            function deleteTask(taskId) {
                tasks = tasks.filter(t => t.id !== taskId);
                saveTasks();
                render();
            }

            // ---------- 事件绑定 ----------
            // 添加按钮点击
            addBtn.addEventListener('click', addTask);

            // 输入框回车提交
            taskInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault(); // 防止任何意外提交行为
                    addTask();
                }
            });

            // 可选：点击空白区域不处理，但保持输入框焦点友好
            // 初始化加载
            function init() {
                loadTasks();
                render();
                // 自动聚焦输入框，方便直接输入
                taskInput.focus();
            }

            // 启动应用
            init();
        })();
    </script>
</body>
</html>
