<body>
  <div class="todo-card">
    <h1>
      ✅ 待办清单
      <span id="taskCounter">0</span>
    </h1>
    <div class="subhead">所有任务自动保存在浏览器中，下次打开依然可见</div>

    <!-- 新增任务 -->
    <div class="add-task">
      <input type="text" id="taskInput" placeholder="写一个任务…" autocomplete="off" aria-label="新任务内容">
      <button id="addBtn" aria-label="添加任务">➕ 添加</button>
    </div>

    <!-- 任务列表容器 -->
    <ul class="task-list" id="taskList">
      <!-- 动态渲染任务 -->
    </ul>

    <!-- 底部统计与清除 -->
    <div class="stats">
      <span id="statsText">0 项任务</span>
      <button class="clear-completed" id="clearCompletedBtn" aria-label="清除已完成任务">清除已完成</button>
    </div>
  </div>

  <script>
    (function() {
      // ---------- 存储键名 ----------
      const STORAGE_KEY = 'todo_list_data_v1';

      // ---------- 状态 ----------
      let tasks = [];          // 任务数组: { id: string, text: string, completed: boolean }

      // ---------- DOM 元素 ----------
      const taskInput = document.getElementById('taskInput');
      const addBtn = document.getElementById('addBtn');
      const taskList = document.getElementById('taskList');
      const taskCounter = document.getElementById('taskCounter');
      const statsText = document.getElementById('statsText');
      const clearCompletedBtn = document.getElementById('clearCompletedBtn');

      // ---------- 工具函数 ----------
      // 生成唯一ID (简单且够用)
      function generateId() {
        return Date.now() + '-' + Math.random().toString(36).substring(2, 10);
      }

      // 从 localStorage 加载数据
      function loadTasks() {
        try {
          const stored = localStorage.getItem(STORAGE_KEY);
          if (stored) {
            const parsed = JSON.parse(stored);
            if (Array.isArray(parsed)) {
              // 简单校验每个任务的结构，防止脏数据
              tasks = parsed.filter(task => 
                task && typeof task === 'object' && 
                typeof task.id === 'string' && 
                typeof task.text === 'string' && 
                typeof task.completed === 'boolean'
              );
            } else {
              tasks = [];
            }
          } else {
            tasks = [];
          }
        } catch (e) {
          console.warn('读取本地存储失败，使用空列表', e);
          tasks = [];
        }
      }

      // 保存到 localStorage
      function saveTasks() {
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
        } catch (e) {
          console.warn('保存到本地存储失败（可能是存储空间已满）', e);
        }
      }

      // ---------- 渲染任务列表 ----------
      function render() {
        // 清空列表
        taskList.innerHTML = '';

        // 如果没有任务，显示空状态
        if (tasks.length === 0) {
          const emptyDiv = document.createElement('li');
          emptyDiv.className = 'empty-message';
          emptyDiv.textContent = '✨ 还没有任务，添加一条吧';
          taskList.appendChild(emptyDiv);
        } else {
          // 遍历任务并创建 DOM
          tasks.forEach(task => {
            const li = document.createElement('li');
            li.className = 'task-item' + (task.completed ? ' completed' : '');
            li.dataset.id = task.id;

            // 复选框
            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.className = 'task-check';
            checkbox.checked = task.completed;
            checkbox.setAttribute('aria-label', `标记任务“${task.text}”为${task.completed ? '未完成' : '已完成'}`);
            // 使用 change 事件监听勾选
            checkbox.addEventListener('change', (e) => {
              e.stopPropagation();
              toggleTask(task.id);
            });

            // 任务文本
            const textSpan = document.createElement('span');
            textSpan.className = 'task-text';
            textSpan.textContent = task.text;

            // 删除按钮
            const delBtn = document.createElement('button');
            delBtn.className = 'delete-btn';
            delBtn.innerHTML = '✕';  // 乘号作为删除图标
            delBtn.setAttribute('aria-label', `删除任务“${task.text}”`);
            delBtn.addEventListener('click', (e) => {
              e.stopPropagation();
              deleteTask(task.id);
            });

            li.appendChild(checkbox);
            li.appendChild(textSpan);
            li.appendChild(delBtn);
            taskList.appendChild(li);
          });
        }

        // 更新统计信息
        updateStats();
      }

      // 更新计数器与统计文本
      function updateStats() {
        const total = tasks.length;
        const completedCount = tasks.filter(t => t.completed).length;
        const activeCount = total - completedCount;

        // 顶部徽章显示未完成数量（更直观）
        taskCounter.textContent = activeCount;

        // 底部统计
        if (total === 0) {
          statsText.textContent = '0 项任务';
        } else {
          statsText.textContent = `${activeCount} 项未完成 / ${total} 项总计`;
        }
      }

      // ---------- 核心操作 ----------
      // 添加任务
      function addTask() {
        const text = taskInput.value.trim();
        if (text === '') {
          // 简单提示：输入框抖动或聚焦
          taskInput.focus();
          taskInput.style.borderColor = '#d14545';
          setTimeout(() => {
            taskInput.style.borderColor = '#e2e8f0';
          }, 300);
          return;
        }

        const newTask = {
          id: generateId(),
          text: text,
          completed: false
        };

        tasks.push(newTask);
        saveTasks();
        render();

        // 清空输入框并保持焦点
        taskInput.value = '';
        taskInput.focus();
      }

      // 切换完成状态
      function toggleTask(id) {
        const task = tasks.find(t => t.id === id);
        if (task) {
          task.completed = !task.completed;
          saveTasks();
          render();  // 重新渲染以更新样式和统计
        }
      }

      // 删除任务
      function deleteTask(id) {
        tasks = tasks.filter(t => t.id !== id);
        saveTasks();
        render();
      }

      // 清除所有已完成任务
      function clearCompleted() {
        const hasCompleted = tasks.some(t => t.completed);
        if (!hasCompleted) return;  // 没有已完成任务时不做任何事

        tasks = tasks.filter(t => !t.completed);
        saveTasks();
        render();
      }

      // ---------- 初始化与事件绑定 ----------
      function init() {
        // 从本地存储加载数据
        loadTasks();
        // 首次渲染
        render();

        // 添加按钮点击事件
        addBtn.addEventListener('click', addTask);

        // 输入框回车添加
        taskInput.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            addTask();
          }
        });

        // 清除已完成按钮
        clearCompletedBtn.addEventListener('click', clearCompleted);

        // 可选：点击输入框时移除错误边框
        taskInput.addEventListener('input', () => {
          taskInput.style.borderColor = '#e2e8f0';
        });
      }

      // 启动应用
      init();
    })();
  </script>
</body>
</html>
```
### 功能与操作说明

您可以像使用一个轻量级应用一样管理任务。它的核心操作非常直观：

- **新增任务**：在输入框中输入内容后，点击“添加”按钮或按回车键，任务就会出现在列表中。
- **标记完成**：点击任务左侧的圆形复选框，任务文本会变为带删除线的灰色样式，表示已完成。
