  <script>
    (function() {
      'use strict';

      // ---------- 常量与状态 ----------
      const STORAGE_KEY = 'todo_list_app_v1';

      // 从 localStorage 读取任务，若不存在或解析失败则返回空数组
      function loadTodos() {
        try {
          const raw = localStorage.getItem(STORAGE_KEY);
          if (!raw) return [];
          const parsed = JSON.parse(raw);
          // 确保是数组，并且每个元素有 id, text, completed 字段
          if (!Array.isArray(parsed)) return [];
          return parsed.filter(item =>
            item && typeof item === 'object' &&
            typeof item.id === 'string' &&
            typeof item.text === 'string' &&
            typeof item.completed === 'boolean'
          );
        } catch (e) {
          console.warn('读取本地任务失败，将使用空列表', e);
          return [];
        }
      }

      // 保存任务到 localStorage
      function saveTodos(todos) {
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
        } catch (e) {
          console.warn('保存任务到 localStorage 失败', e);
        }
      }

      // 生成唯一 id (简单但足够)
      function generateId() {
        return Date.now().toString(36) + '-' + Math.random().toString(36).substring(2, 9);
      }

      // ---------- DOM 元素 ----------
      const todoInput = document.getElementById('todoInput');
      const addBtn = document.getElementById('addBtn');
      const todoListEl = document.getElementById('todoList');
      const emptyStateEl = document.getElementById('emptyState');
      const statsTextEl = document.getElementById('statsText');
      const clearCompletedBtn = document.getElementById('clearCompletedBtn');

      // ---------- 应用状态 ----------
      let todos = loadTodos();   // 任务数组

      // ---------- 渲染 ----------
      function render() {
        // 清空列表
        todoListEl.innerHTML = '';

        // 根据任务数量显示/隐藏空状态
        if (todos.length === 0) {
          emptyStateEl.style.display = 'block';
        } else {
          emptyStateEl.style.display = 'none';
        }

        // 遍历 todos 生成列表项
        todos.forEach(todo => {
          const li = document.createElement('li');
          li.className = 'todo-item' + (todo.completed ? ' completed' : '');
          li.dataset.id = todo.id;

          // 复选框
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.className = 'todo-check';
          checkbox.checked = todo.completed;
          checkbox.setAttribute('aria-label', `标记任务“${todo.text}”为${todo.completed ? '未完成' : '已完成'}`);
          // 使用事件委托也可以，但直接绑定更清晰
          checkbox.addEventListener('change', (e) => {
            e.stopPropagation();
            toggleTodo(todo.id);
          });

          // 任务文本
          const span = document.createElement('span');
          span.className = 'todo-text';
          span.textContent = todo.text;

          // 删除按钮
          const delBtn = document.createElement('button');
          delBtn.className = 'delete-btn';
          delBtn.innerHTML = '✕';   // 乘号字符，不依赖图标库
          delBtn.setAttribute('aria-label', `删除任务“${todo.text}”`);
          delBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            deleteTodo(todo.id);
          });

          li.appendChild(checkbox);
          li.appendChild(span);
          li.appendChild(delBtn);
          todoListEl.appendChild(li);
        });

        // 更新底部统计
        updateStats();
      }

      // 更新统计信息
      function updateStats() {
        const total = todos.length;
        const completedCount = todos.filter(t => t.completed).length;
        if (total === 0) {
          statsTextEl.textContent = '0 项任务';
        } else {
          statsTextEl.textContent = `${total} 项任务 · 已完成 ${completedCount}`;
        }
      }

      // ---------- 操作函数 ----------

      // 添加任务
      function addTodo() {
        const text = todoInput.value.trim();
        if (text === '') {
          // 空内容不添加，可以轻微提示（输入框聚焦）
          todoInput.focus();
          return;
        }

        const newTodo = {
          id: generateId(),
          text: text,
          completed: false
        };

        todos.push(newTodo);
        saveTodos(todos);
        render();

        // 清空输入框并保持焦点
        todoInput.value = '';
        todoInput.focus();
      }

      // 切换完成状态
      function toggleTodo(id) {
        const todo = todos.find(t => t.id === id);
        if (!todo) return;
        todo.completed = !todo.completed;
        saveTodos(todos);
        render();
      }

      // 删除单条任务
      function deleteTodo(id) {
        todos = todos.filter(t => t.id !== id);
        saveTodos(todos);
        render();
      }

      // 清除所有已完成任务
      function clearCompleted() {
        const hasCompleted = todos.some(t => t.completed);
        if (!hasCompleted) return;   // 没有已完成任务时不做任何事
        todos = todos.filter(t => !t.completed);
        saveTodos(todos);
        render();
      }

      // ---------- 事件绑定 ----------
      addBtn.addEventListener('click', addTodo);

      // 输入框按回车添加
      todoInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          addTodo();
        }
      });

      // 清除已完成按钮
      clearCompletedBtn.addEventListener('click', clearCompleted);

      // ---------- 初始化渲染 ----------
      render();

      // 可选：当页面从 bfcache 恢复时重新读取 localStorage（保证多标签页同步）
      window.addEventListener('pageshow', (event) => {
        if (event.persisted) {
          // 从缓存恢复，重新加载数据并渲染
          todos = loadTodos();
          render();
        }
      });

      // 监听 storage 事件，实现多标签页同步（可选但实用）
      window.addEventListener('storage', (e) => {
        if (e.key === STORAGE_KEY) {
          todos = loadTodos();
          render();
        }
      });

    })();
  </script>
</body>
</html>
```
### 功能与操作说明

您可以轻松地添加、勾选和删除任务，所有操作都会即时保存。

- **新增任务**：在输入框中输入内容后点击“添加”按钮或按回车键即可。如果输入框为空，则不会添加任何任务。
- **标记完成**：点击任务左侧的复选框可以切换完成状态。已完成的任务会显示为灰色背景并带有删除线，方便区分。
- **删除任务**：点击任务右侧的“✕”按钮可以删除单条任务。底部的“清除已完成”按钮可以一次性删除所有已完成的任务。
- **数据持久化**：所有任务都会自动保存在浏览器的 localStorage 中。关闭页面或刷新后，再次打开时任务和完成状态都会保留。

