<body>
    <div class="app">
        <h1>
            📋 待办清单
            <span id="taskCounter">0</span>
        </h1>
        <div class="subhead">所有任务自动保存在浏览器中</div>

        <div class="input-area">
            <input type="text" id="taskInput" placeholder="写一个任务，比如 “买牛奶”" autocomplete="off" maxlength="200">
            <button id="addBtn">+ 添加</button>
        </div>

        <div class="stats">
            <span class="count" id="statsText">0 项任务</span>
            <button class="clear-btn" id="clearCompletedBtn">清除已完成</button>
        </div>

        <ul class="todo-list" id="todoList"></ul>

        <div class="footer-note">
            ⚡ 点击复选框标记完成 · 点击 ✕ 删除任务
        </div>
    </div>

    <script>
        (function() {
            // ---------- 存储键名 ----------
            const STORAGE_KEY = 'todo_list_app_v1';

            // ---------- 数据 ----------
            let todos = [];          // { id: string, text: string, completed: boolean }

            // ---------- DOM 元素 ----------
            const taskInput = document.getElementById('taskInput');
            const addBtn = document.getElementById('addBtn');
            const todoList = document.getElementById('todoList');
            const taskCounter = document.getElementById('taskCounter');
            const statsText = document.getElementById('statsText');
            const clearCompletedBtn = document.getElementById('clearCompletedBtn');

            // ---------- 工具函数 ----------
            // 生成唯一ID (简单且够用)
            function generateId() {
                return Date.now().toString(36) + Math.random().toString(36).substring(2, 8);
            }

            // 从 localStorage 加载数据
            function loadFromStorage() {
                try {
                    const stored = localStorage.getItem(STORAGE_KEY);
                    if (stored) {
                        const parsed = JSON.parse(stored);
                        if (Array.isArray(parsed)) {
                            // 过滤掉无效数据，保证结构正确
                            todos = parsed.filter(item => 
                                item && typeof item === 'object' && 
                                typeof item.id === 'string' && 
                                typeof item.text === 'string' && 
                                typeof item.completed === 'boolean'
                            );
                        } else {
                            todos = [];
                        }
                    } else {
                        todos = [];
                    }
                } catch (e) {
                    console.warn('读取本地存储失败，使用空列表', e);
                    todos = [];
                }
            }

            // 保存到 localStorage
            function saveToStorage() {
                try {
                    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
                } catch (e) {
                    console.warn('保存到本地存储失败', e);
                }
            }

            // 更新界面统计信息
            function updateStats() {
                const total = todos.length;
                const completedCount = todos.filter(t => t.completed).length;
                const activeCount = total - completedCount;

                taskCounter.textContent = total;
                if (total === 0) {
                    statsText.textContent = '0 项任务';
                } else {
                    statsText.textContent = `${activeCount} 项待办 · ${completedCount} 项已完成`;
                }
            }

            // 渲染整个列表
            function render() {
                // 清空列表
                todoList.innerHTML = '';

                if (todos.length === 0) {
                    // 显示空状态
                    const emptyDiv = document.createElement('div');
                    emptyDiv.className = 'empty-state';
                    emptyDiv.innerHTML = '<span>📝</span>还没有任务，添加一条吧';
                    todoList.appendChild(emptyDiv);
                } else {
                    // 按顺序渲染每一项
                    todos.forEach(todo => {
                        const li = document.createElement('li');
                        li.className = `todo-item ${todo.completed ? 'completed' : ''}`;
                        li.dataset.id = todo.id;

                        // 复选框容器
                        const checkboxWrapper = document.createElement('div');
                        checkboxWrapper.className = 'checkbox-wrapper';

                        const checkbox = document.createElement('input');
                        checkbox.type = 'checkbox';
                        checkbox.className = 'todo-checkbox';
                        checkbox.checked = todo.completed;
                        // 用 change 事件监听勾选
                        checkbox.addEventListener('change', (e) => {
                            e.stopPropagation();
                            toggleTodo(todo.id);
                        });

                        checkboxWrapper.appendChild(checkbox);

                        // 任务文本
                        const textSpan = document.createElement('span');
                        textSpan.className = 'todo-text';
                        textSpan.textContent = todo.text;

                        // 删除按钮
                        const deleteBtn = document.createElement('button');
                        deleteBtn.className = 'delete-btn';
                        deleteBtn.innerHTML = '✕';
                        deleteBtn.setAttribute('aria-label', '删除任务');
                        deleteBtn.addEventListener('click', (e) => {
                            e.stopPropagation();
                            deleteTodo(todo.id);
                        });

                        li.appendChild(checkboxWrapper);
                        li.appendChild(textSpan);
                        li.appendChild(deleteBtn);

                        todoList.appendChild(li);
                    });
                }

                // 更新统计
                updateStats();
            }

            // ---------- 核心操作 ----------
            // 添加任务
            function addTodo() {
                const text = taskInput.value.trim();
                if (text === '') {
                    // 简单提示：输入框抖动或聚焦
                    taskInput.focus();
                    taskInput.style.borderColor = '#f87171';
                    setTimeout(() => {
                        taskInput.style.borderColor = '#e2e8f0';
                    }, 300);
                    return;
                }

                const newTodo = {
                    id: generateId(),
                    text: text,
                    completed: false
                };

                todos.push(newTodo);
                saveToStorage();
                render();

                // 清空输入框并聚焦
                taskInput.value = '';
                taskInput.focus();
            }

            // 切换完成状态
            function toggleTodo(id) {
                const todo = todos.find(t => t.id === id);
                if (todo) {
                    todo.completed = !todo.completed;
                    saveToStorage();
                    render();  // 重新渲染以更新样式和统计
                }
            }

            // 删除任务
            function deleteTodo(id) {
                todos = todos.filter(t => t.id !== id);
                saveToStorage();
                render();
            }

            // 清除所有已完成任务
            function clearCompleted() {
                const completedCount = todos.filter(t => t.completed).length;
                if (completedCount === 0) return;  // 没有已完成任务，不操作

                todos = todos.filter(t => !t.completed);
                saveToStorage();
                render();
            }

            // ---------- 初始化与事件绑定 ----------
            function init() {
                // 从本地存储加载数据
                loadFromStorage();
                // 首次渲染
                render();

                // 添加按钮点击
                addBtn.addEventListener('click', addTodo);

                // 输入框回车添加
                taskInput.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter') {
                        e.preventDefault();
                        addTodo();
                    }
                });

                // 清除已完成按钮
                clearCompletedBtn.addEventListener('click', clearCompleted);

                // 输入框聚焦时恢复边框颜色（如果之前有错误提示）
                taskInput.addEventListener('focus', () => {
                    taskInput.style.borderColor = '#818cf8';
                });
                taskInput.addEventListener('blur', () => {
                    taskInput.style.borderColor = '#e2e8f0';
                });
            }

            // 启动应用
            init();
        })();
    </script>
</body>
</html>
